SysDataModelXML.SQLUpdateScript:
--LINKJSONDATASUBMIT DECLARE @USER VARCHAR(30) = '#LOGIN_USER#'; DECLARE @CRETIM DATETIME = GETDATE(); DECLARE @BATCHID VARCHAR(50) ='NEW-PRCIMP-#LOGIN_USER#';
DECLARE @json NVARCHAR(MAX); SET @json = N'#LINKJSON{$.TABLE_1}#';
DECLARE @FILENAM NVARCHAR(100); SET @FILENAM = N'#LINKJSON{$.formData.FILENAM}#';
MERGE INTO [STKLOTLST] K USING ( SELECT * FROM OPENJSON(@json) WITH ( LOT varchar(30) '$.LOT' ,SUBLOT varchar(30) '$.SUBLOT' ,TAGNO varchar(30) '$.TAGNO' ,MIC decimal(18,6) '$.MIC' ,LEN decimal(18,6) '$.LEN' ,UNIF decimal(18,6) '$.UNIF' ,STR decimal(18,6) '$.STR' ,RD decimal(18,6) '$.RD' ,PLUSB decimal(18,6) '$.PLUSB' ,RECWT decimal(18,6) '$.RECWT' ,NETREWT decimal(18,6) '$.NETREWT' ,SHIPWT decimal(18,6) '$.SHIPWT' ,NETSHWT decimal(18,6) '$.NETSHWT' ,TAREWT decimal(18,6) '$.TAREWT' ,CONTRACT varchar(50) '$.CONTRACT' ,INVOICE varchar(50) '$.INVOICE' )) S ON S.TAGNO = K.TAGNO WHEN NOT MATCHED THEN INSERT (LOT, SUBLOT, TAGTYP, TAGNO, MIC, LEN, UNIF, STR, RD, PLUSB, RECWT, NETREWT, SHIPWT,NETSHWT,TAREWT, CONTRACT, INVOICE, FILENAM, CREUSR, BATCHID, DOCSTA, SUBSTA, DOCTYP, DOCGRP) VALUES (LTRIM(RTRIM(S.LOT)), LTRIM(RTRIM(S.SUBLOT)), 'CTR', LTRIM(RTRIM(S.TAGNO)), S.MIC, S.LEN, S.UNIF, S.STR, S.RD, S.PLUSB, S.RECWT, S.NETREWT, S.SHIPWT,S.NETSHWT,S.TAREWT, S.CONTRACT, S.INVOICE, @FILENAM, @USER, @BATCHID, '1', 1, 'PRC', 'IMP'); -- 插入的记录标记为DOCSTA=1
UPDATE STKLOTLST SET SITE = H.SITE ,ITMNO = D.ITMNO ,ITMVER = D.ITMVER ,SRCTYP = D.SRCTYP ,SRCDOC = D.SRCDOC ,SRCLIN = D.SRCLIN ,ORITYP = H.DOCTYP ,ORIDOC = D.DOCNUM ,ORILIN = D.DOCLIN ,BPRNO = H.BPSNO ,FAC = D.FAC ,UOM = 'PKG' ,UOMCOE = ROUND(D.CTRQTY,2) --均重 ,QTY = 1 ,QTYSTU = ROUND(D.CTRQTY,2) --均重 ,STU = ITM.STU FROM STKLOTLST S WITH (NOLOCK) INNER JOIN PBOLD D ON S.LOT = D.LOT INNER JOIN PBOLH H ON D.DOCNUM = H.DOCNUM INNER JOIN ITM ON ITM.ITMNO = D.ITMNO WHERE S.BATCHID = @BATCHID
